/* Seven original projects, presented as an accessible expanding bookshelf. */
window.createPortfolioBookShelf=function({panel,projects,group,openProject,reduced}){
 const escape=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
 const colors=['#a1c9cb','#acc1e1','#a7cfb5','#d9b7ae','#bbacd1','#dfc18d','#b7c8db'];
 panel.classList.add('folder-books');
 panel.insertAdjacentHTML('beforeend',`<div class="campaign-shelf" aria-label="整合营销项目书架"><div class="campaign-books" role="tablist" aria-label="七个整合营销项目">${projects.map((p,i)=>`<button type="button" class="campaign-book" role="tab" id="campaign-tab-${i}" aria-controls="campaign-details" aria-selected="${i===0}" tabindex="${i===0?0:-1}" style="--book-color:${colors[i]}"><span class="campaign-spine"><small>${String(i+1).padStart(2,'0')}</small><span>${escape(p.title)}</span><small>${escape(p.year)}</small></span><span class="campaign-face" aria-hidden="true"><span class="campaign-edition">${String(i+1).padStart(2,'0')} / ${escape(p.year)}</span><img src="${escape(p.cover)}" alt="" loading="lazy" decoding="async" draggable="false"><span class="campaign-cover-title">${escape(p.title)}</span></span></button>`).join('')}</div></div><div class="campaign-details" id="campaign-details" role="tabpanel" aria-labelledby="campaign-tab-0"><div class="campaign-selection"><span class="campaign-count"></span><h4 class="campaign-title"></h4><p class="campaign-summary"></p><div class="campaign-tags"></div></div><a class="campaign-open">查看项目 ↗</a></div><div class="campaign-controls"><button type="button" class="campaign-prev" aria-label="上一个整合营销项目">← 上一册</button><span class="campaign-hint">点击书脊展开 · 滚轮或左右拖动切换</span><button type="button" class="campaign-auto" aria-pressed="false">自动翻阅</button><button type="button" class="campaign-next" aria-label="下一个整合营销项目">下一册 →</button></div><p class="campaign-status sr-only" role="status" aria-live="polite"></p>`);
 const shelf=panel.querySelector('.campaign-shelf'),tabs=[...panel.querySelectorAll('.campaign-book')],details=panel.querySelector('.campaign-details'),link=panel.querySelector('.campaign-open'),auto=panel.querySelector('.campaign-auto');
 let index=0,enabled=true,visible=false,playing=false,hovered=false,focused=false,timer=0,drag=null,suppressUntil=0,wheel=0,lastWheel=0;
 const key='portfolio-integrated-books';
 function rememberDirectory(){try{sessionStorage.setItem(key,projects[index].id)}catch{}}
 function schedule(){clearTimeout(timer);if(enabled&&visible&&playing&&!reduced.matches&&!hovered&&!focused&&!document.hidden&&!document.querySelector('dialog[open]'))timer=setTimeout(()=>{select((index+1)%projects.length);schedule()},4200)}
 function select(i,manual=false){index=Math.max(0,Math.min(projects.length-1,i));const p=projects[index];tabs.forEach((b,j)=>{b.setAttribute('aria-selected',String(j===index));b.tabIndex=j===index?0:-1});details.setAttribute('aria-labelledby',tabs[index].id);panel.querySelector('.campaign-count').textContent=`${String(index+1).padStart(2,'0')} / ${String(projects.length).padStart(2,'0')} · ${p.year}`;panel.querySelector('.campaign-title').textContent=p.title;panel.querySelector('.campaign-summary').textContent=p.summary;panel.querySelector('.campaign-tags').replaceChildren(...p.tags.map(t=>{const el=document.createElement('span');el.textContent=t;return el}));link.href=p.entry;link.setAttribute('aria-label','查看'+p.title+'的项目详情');panel.querySelector('.campaign-prev').disabled=index===0;panel.querySelector('.campaign-next').disabled=index===projects.length-1;if(manual){rememberDirectory();panel.querySelector('.campaign-status').textContent=`第 ${index+1} 册，${p.title}`;}schedule()}
 tabs.forEach((b,i)=>b.addEventListener('click',e=>{if(performance.now()<suppressUntil){e.preventDefault();return}select(i,true)}));
 panel.querySelector('.campaign-books').addEventListener('keydown',e=>{const at=tabs.indexOf(document.activeElement);if(at<0)return;let next;if(['ArrowRight','ArrowDown'].includes(e.key))next=Math.min(index+1,projects.length-1);else if(['ArrowLeft','ArrowUp'].includes(e.key))next=Math.max(index-1,0);else if(e.key==='Home')next=0;else if(e.key==='End')next=projects.length-1;else return;e.preventDefault();select(next,true);tabs[next].focus({preventScroll:true})});
 link.addEventListener('click',e=>{rememberDirectory();openProject(e,projects[index],link)});
 panel.querySelector('.campaign-prev').addEventListener('click',()=>select(index-1,true));panel.querySelector('.campaign-next').addEventListener('click',()=>select(index+1,true));
 auto.addEventListener('click',()=>{playing=!playing;if(playing)focused=false;auto.setAttribute('aria-pressed',String(playing));auto.textContent=playing?'暂停翻阅':'自动翻阅';schedule()});
 shelf.addEventListener('wheel',e=>{if(!enabled||!visible||e.ctrlKey||e.metaKey)return;const delta=Math.abs(e.deltaX)>Math.abs(e.deltaY)?e.deltaX:e.deltaY;if(!delta||(index===0&&delta<0)||(index===projects.length-1&&delta>0))return;e.preventDefault();if(performance.now()-lastWheel<450)return;wheel+=delta;if(Math.abs(wheel)>=65){select(index+Math.sign(wheel),true);lastWheel=performance.now();wheel=0}},{passive:false});
 shelf.addEventListener('pointerdown',e=>{if(e.button!==0)return;drag={id:e.pointerId,x:e.clientX,y:e.clientY,horizontal:false}});
 shelf.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(!drag.horizontal&&Math.abs(dx)>12&&Math.abs(dx)>Math.abs(dy)){drag.horizontal=true;shelf.setPointerCapture(e.pointerId)}});
 shelf.addEventListener('pointerup',e=>{if(!drag||drag.id!==e.pointerId)return;const dx=e.clientX-drag.x;if(drag.horizontal){suppressUntil=performance.now()+350;if(Math.abs(dx)>40)select(index+(dx<0?1:-1),true);if(shelf.hasPointerCapture(e.pointerId))shelf.releasePointerCapture(e.pointerId)}drag=null});shelf.addEventListener('pointercancel',()=>{drag=null});
 shelf.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse'){hovered=true;schedule()}});shelf.addEventListener('pointerleave',()=>{hovered=false;wheel=0;schedule()});
 panel.addEventListener('focusin',()=>{focused=true;schedule()});panel.addEventListener('focusout',e=>{if(!panel.contains(e.relatedTarget)){focused=false;schedule()}});
 new IntersectionObserver(es=>{visible=es[0].isIntersecting;schedule()},{threshold:.2}).observe(shelf);document.addEventListener('visibilitychange',schedule);reduced.addEventListener('change',schedule);window.addEventListener('portfolio-film-open',schedule);window.addEventListener('portfolio-film-close',schedule);
 select(0);
 return {setActive(value){enabled=value;schedule()},getCurrent(){return projects[index]},selectProject(id){const i=projects.findIndex(p=>p.id===id);if(i>=0)select(i);return link},rememberDirectory,restoreDirectory(){try{const id=sessionStorage.getItem(key),i=projects.findIndex(p=>p.id===id);if(i>=0)select(i)}catch{}}};
};
